# <<< SPEC

# >>> HINTS
# <<< HINTS

# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_config_key() {
    yarn config list --json 2>/dev/null | jq -b -r 'select(.type == "inspect") | .data | keys[]'
}

_choice_dependency() {
    local pkg
    pkg="$(_argc_util_path_search_parent package.json)" || return 0
    [[ -n "$pkg" ]] || return 0
    jq -b -r '(.dependencies // {}), (.devDependencies // {}), (.optionalDependencies // {}) | keys[]' "$pkg" 2>/dev/null
}

_choice_global_dependency() {
    local dir pkg
    dir="$(yarn global dir 2>/dev/null)" || return 0
    [[ -n "$dir" ]] || return 0
    pkg="$dir/package.json"
    [[ -f "$pkg" ]] || return 0
    jq -b -r '(.dependencies // {}), (.devDependencies // {}), (.optionalDependencies // {}) | keys[]' "$pkg" 2>/dev/null
}

_choice_group() {
    printf '%s\n' dependencies devDependencies optionalDependencies
}

_choice_script() {
    local pkg
    pkg="$(_argc_util_path_search_parent package.json)" || return 0
    [[ -n "$pkg" ]] || return 0
    jq -b -r '(.scripts // {}) | keys[]' "$pkg" 2>/dev/null
}

_choice_workspace() {
    yarn workspaces info 2>/dev/null | sed -n '/^{/,/^}/p' | jq -b -r 'keys[]' 2>/dev/null
}

_choice_workspace_args() {
    local location
    location="$(_helper_workspace_location "${argc_workspace_name:-}")"
    [[ -n "$location" && -d "$location" ]] || return 0
    (cd "$location" && _argc_util_comp_subcommand 1 yarn)
}

_choice_workspaces_cmd() {
    _argc_util_comp_subcommand 0 yarn
}

_helper_workspace_location() {
    [[ -n "$1" ]] || return 0
    yarn workspaces info 2>/dev/null | sed -n '/^{/,/^}/p' | jq -b -r --arg n "$1" '.[$n].location // empty' 2>/dev/null
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
